import React from 'react';
import { useNavigate } from 'react-router-dom';

const services = [
  {
    id: 1,
    title: "Tổ chức tiệc cưới",
    desc: "Tổ chức lễ cưới chuyên nghiệp, sang trọng và theo yêu cầu cá nhân hóa cho từng cặp đôi.",
    path: "/service/wedding"
  },
  {
    id: 2,
    title: "Sinh nhật & Kỷ niệm",
    desc: "Trang trí và tổ chức tiệc sinh nhật, kỷ niệm với nhiều phong cách và gói dịch vụ linh hoạt.",
    path: "/service/birthday"
  },
  {
    id: 3,
    title: "Sự kiện công ty",
    desc: "Tổ chức hội nghị, gala dinner, team building với quy mô từ nhỏ đến lớn, chuyên nghiệp và hiệu quả.",
    path: "/service/corporate"
  },
  {
    id: 4,
    title: "Trang trí tiệc theo chủ đề",
    desc: "Cung cấp dịch vụ trang trí không gian tiệc theo các chủ đề độc đáo và phong cách.",
    path: "/service/decor"
  }
];

function Home() {
  const navigate = useNavigate();
  const isLoggedIn = !!JSON.parse(localStorage.getItem("currentUser"));

  const handleClick = (path) => {
    if (isLoggedIn) {
      navigate(path);
    } else {
      alert("Vui lòng đăng nhập để xem chi tiết dịch vụ.");
      navigate("/login");
    }
  };

  return (
    <div className="container py-5">
      <div className="bg-gradient p-5 text-white rounded text-center mb-5" style={{ background: "linear-gradient(to right, #f093fb, #f5576c)" }}>
      <h1 className="mb-3">Biến mọi dịp thành lễ hội đáng nhớ</h1>
      <p className="fs-5">Dịch vụ tổ chức tiệc đa dạng – linh hoạt – đầy cảm hứng</p>
    </div>
    <div className="row">
      {services.map(s => (
        <div className="col-sm-6 col-lg-3 mb-4" key={s.id}>
          <div className="card border-0 shadow h-100">
            <div className="card-body text-center">
              <h5 className="card-title">{s.title}</h5>
              <p className="card-text">{s.desc}</p>
              <button className="btn btn-pink" onClick={() => handleClick(s.path)}>Xem ngay</button>
            </div>
          </div>
        </div>
      ))}
    </div>
  </div>

  );
}

export default Home;
